from pathlib import Path
import pandas as pd

input_dir = Path('input')
output_dir = Path('prepared')
output_dir.mkdir(parents=True, exist_ok=True)

def read_mapped(filename, mapping):
    frame = pd.read_csv(input_dir / filename)
    missing = set(mapping) - set(frame.columns)
    if missing:
        raise ValueError(f'{filename} is missing columns: {sorted(missing)}')
    result = frame.loc[:, list(mapping)].rename(columns=mapping).copy()
    result['hole_id'] = result['hole_id'].astype('string').str.strip()
    if result['hole_id'].isna().any() or result['hole_id'].eq('').any():
        raise ValueError(f'{filename} contains a blank hole ID')
    for column in result.columns.drop('hole_id'):
        result[column] = pd.to_numeric(result[column], errors='coerce')
        if result[column].isna().any():
            raise ValueError(f'{filename} contains missing or nonnumeric values in {column}')
    return result

collars = read_mapped('collar.csv', {
    'HOLE_ID': 'hole_id', 'EASTING': 'easting', 'NORTHING': 'northing',
    'ELEVATION': 'elevation', 'FINAL_DEPTH': 'total_depth'
})
surveys = read_mapped('survey.csv', {
    'HOLE_ID': 'hole_id', 'DEPTH': 'depth', 'AZIMUTH': 'azimuth', 'DIP': 'dip'
})
assays = read_mapped('assays.csv', {
    'HOLE_ID': 'hole_id', 'FROM': 'from_depth', 'TO': 'to_depth', 'CU_PCT': 'cu_pct'
})

if collars['hole_id'].duplicated().any():
    raise ValueError('Collar table contains duplicate hole IDs')
if (collars['total_depth'] <= 0).any():
    raise ValueError('Every collar total depth must be positive')
if ((surveys['depth'] < 0) | (surveys['dip'] < -90) | (surveys['dip'] > 90) |
        (surveys['azimuth'] < 0) | (surveys['azimuth'] >= 360)).any():
    raise ValueError('Survey depths, dips, or azimuths are outside their valid ranges')
if ((assays['from_depth'] < 0) | (assays['to_depth'] <= assays['from_depth'])).any():
    raise ValueError('Assay intervals must have nonnegative starts and positive lengths')

depths = collars.set_index('hole_id')['total_depth']
for name, table, end_column in (
    ('survey', surveys, 'depth'), ('assay', assays, 'to_depth')
):
    limits = table['hole_id'].map(depths)
    if limits.isna().any():
        raise ValueError(f'{name} table contains hole IDs absent from the collar table')
    if (table[end_column] > limits + 1e-8).any():
        raise ValueError(f'{name} depths exceed the collar total depth')

collars.sort_values('hole_id').to_csv(output_dir / 'collar.csv', index=False)
